import { gsap } from 'gsap';
import {
  MeshBasicNodeMaterial,
  PlaneGeometry,
  DoubleSide,
  Group,
  Mesh,
  Color,
} from 'three/webgpu';
import {
  uv,
  vec2,
  vec3,
  float,
  mix,
  smoothstep,
  max,
  abs,
  length,
} from 'three/tsl';

export default function createNode(config, ctx) {
  const group = new Group();

  // Position, rotation, scale
  const pos = config.scenePosition || { x: 0, y: 1.6, z: 0 };
  const rot = config.sceneRotation || { x: 0, y: 0, z: 0 };
  const scale = config.sceneScale || { x: 1, y: 1, z: 1 };
  group.position.set(pos.x, pos.y, pos.z);
  group.rotation.set(rot.x, rot.y, rot.z);
  group.scale.set(scale.x, scale.y, scale.z);

  // Geometry – capsule size
  const width = 0.8;
  const height = 0.3;
  const geometry = new PlaneGeometry(width, height);

  // Colors from spec
  const inkColor = new Color('#16161d');
  const accentColor = new Color('#ff2a38');

  // ── TSL shader for rounded capsule with accent edge glow ──
  const uvNode = uv();
  const halfW = float(width * 0.5);
  const halfH = float(height * 0.5);
  const cornerR = float(0.2); // relative to UV space

  const center = vec2(0.5, 0.5);
  const halfSize = vec2(0.5, 0.5);
  const q = abs(uvNode - center) - halfSize + vec2(cornerR);
  const dist = length(max(q, vec2(0.0))) - cornerR;
  const mask = smoothstep(0.005, 0.0, dist);

  // Accent edge light – brightest at top
  const topGlow = smoothstep(0.85, 1.0, uvNode.y());
  const baseColor = vec3(inkColor.r, inkColor.g, inkColor.b);
  const accentVec = vec3(accentColor.r, accentColor.g, accentColor.b);
  const glowed = mix(baseColor, accentVec, topGlow * 0.6);

  const finalColor = vec3(mask) * glowed;

  const material = new MeshBasicNodeMaterial({
    colorNode: finalColor,
    side: DoubleSide,
    transparent: true,
  });

  const mesh = new Mesh(geometry, material);
  group.add(mesh);

  // ── Hover / Click / Press-down behavior ──
  const baseY = group.position.y;
  let hoverTween = null;

  group.userData.handlers = {
    mouseenter: () => {
      if (hoverTween) hoverTween.kill();
      hoverTween = gsap.to(group.position, {
        y: baseY + 0.15,
        duration: 0.3,
        ease: 'power2.out',
        overwrite: true,
      });
    },
    mouseleave: () => {
      if (hoverTween) hoverTween.kill();
      hoverTween = gsap.to(group.position, {
        y: baseY,
        duration: 0.3,
        ease: 'power2.out',
        overwrite: true,
      });
    },
    click: () => {
      ctx.emit('hub-collection.select', {});
    },
    mousedown: () => {
      if (hoverTween) hoverTween.kill();
      hoverTween = gsap.to(group.scale, {
        x: 0.97,
        y: 0.97,
        z: 0.97,
        duration: 0.12,
        ease: 'back.out',
        overwrite: true,
      });
    },
    mouseup: () => {
      if (hoverTween) hoverTween.kill();
      hoverTween = gsap.to(group.scale, {
        x: 1,
        y: 1,
        z: 1,
        duration: 0.12,
        ease: 'back.out',
        overwrite: true,
      });
    },
  };

  // Cleanup
  group.userData.cleanup = () => {
    if (hoverTween) hoverTween.kill();
    geometry.dispose();
    material.dispose();
  };

  return group;
}
